package net.spell_engine.particle;
import net.minecraft.particle.DefaultParticleType; import net.minecraft.particle.ParticleTypes; import net.minecraft.util.Identifier;
public final class Particles { public static class ParticleEntry { public final Identifier id; public final DefaultParticleType particleType; public boolean usesCustomTexture; public ParticleEntry(String name,DefaultParticleType type){id=new Identifier("spell_engine",name);particleType=type;} public ParticleEntry customTexture(){usesCustomTexture=true;return this;} }
 public static final ParticleEntry arcane_spell=new ParticleEntry("arcane_spell",ParticleTypes.ENCHANT); public static final ParticleEntry flame=new ParticleEntry("flame",ParticleTypes.FLAME); public static final ParticleEntry frost_hit=new ParticleEntry("frost_hit",ParticleTypes.SNOWFLAKE); public static final ParticleEntry frost_shard=new ParticleEntry("frost_shard",ParticleTypes.SNOWFLAKE); public static final ParticleEntry snowflake=new ParticleEntry("snowflake",ParticleTypes.SNOWFLAKE); private Particles(){} public static void register(){} }
